"use client";

import { Fragment, useEffect, useState } from "react";
import { FlightsAdmin } from "@/components/FlightsAdmin";
import { MealsAdmin } from "@/components/MealsAdmin";
import { AmenitiesAdmin } from "@/components/AmenitiesAdmin";
import { FeesAdmin } from "@/components/FeesAdmin";
import { BookingDetails } from "@/components/BookingDetails";
import { api, ApiError, bookingStreamUrl } from "@/lib/api";
import type { Booking } from "@/lib/types";
import { formatDateTime, formatMoney } from "@/lib/format";
import { BookingStatusBadge } from "@/components/BookingStatusBadge";
import { useRequireAdmin } from "@/lib/useRequireAdmin";

type Tab = "flights" | "bookings" | "meals" | "amenities" | "fees";

export default function AdminPage() {
  const { ready, isAuthenticated, isAdmin } = useRequireAdmin();
  const [tab, setTab] = useState<Tab>("flights");

  if (!ready || !isAuthenticated || !isAdmin) {
    return <div className="mt-20 text-center text-slate-400">Loading…</div>;
  }

  return (
    <div className="space-y-6">
      <section className="pt-2">
        <h1 className="text-2xl font-bold tracking-tight text-slate-800">
          Admin dashboard
        </h1>
        <p className="mt-1 text-slate-500">
          Manage the flight catalog and watch bookings arrive in real time.
        </p>
      </section>

      <div className="flex flex-wrap gap-1 rounded-xl border border-white/60 bg-white/70 p-1 backdrop-blur sm:w-fit">
        <TabButton active={tab === "flights"} onClick={() => setTab("flights")}>
          ✈ Flights
        </TabButton>
        <TabButton active={tab === "bookings"} onClick={() => setTab("bookings")}>
          ● Bookings (live)
        </TabButton>
        <TabButton active={tab === "meals"} onClick={() => setTab("meals")}>
          🍽 Meals
        </TabButton>
        <TabButton
          active={tab === "amenities"}
          onClick={() => setTab("amenities")}
        >
          ✨ Amenities
        </TabButton>
        <TabButton active={tab === "fees"} onClick={() => setTab("fees")}>
          € Fees &amp; Seats
        </TabButton>
      </div>

      {tab === "flights" && <FlightsAdmin />}
      {tab === "bookings" && <BookingsLive />}
      {tab === "meals" && <MealsAdmin />}
      {tab === "amenities" && <AmenitiesAdmin />}
      {tab === "fees" && <FeesAdmin />}
    </div>
  );
}

function TabButton({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      className={`rounded-lg px-4 py-2 text-sm font-medium transition ${
        active
          ? "bg-gradient-to-r from-indigo-500 to-sky-500 text-white shadow-sm"
          : "text-slate-600 hover:bg-white"
      }`}
    >
      {children}
    </button>
  );
}

function BookingsLive() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [live, setLive] = useState(false);
  const [flashId, setFlashId] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    api
      .listBookings()
      .then((list) => {
        if (active) setBookings(list);
      })
      .catch((err) => {
        if (active)
          setError(
            err instanceof ApiError ? err.message : "Could not load bookings.",
          );
      });
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const source = new EventSource(bookingStreamUrl());
    source.addEventListener("open", () => setLive(true));
    source.addEventListener("booking", (event) => {
      try {
        const booking = JSON.parse((event as MessageEvent).data) as Booking;
        // Upsert: replace an existing row (status change) or prepend a new one.
        setBookings((prev) => {
          const idx = prev.findIndex((b) => b.id === booking.id);
          if (idx === -1) return [booking, ...prev];
          const next = [...prev];
          next[idx] = booking;
          return next;
        });
        setFlashId(booking.id);
        window.setTimeout(() => setFlashId(null), 2500);
      } catch {
        /* ignore malformed event */
      }
    });
    source.onerror = () => setLive(false);
    return () => source.close();
  }, []);

  return (
    <section className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-slate-800">
          Bookings{" "}
          <span className="text-sm font-normal text-slate-400">
            ({bookings.length})
          </span>
        </h2>
        <span
          className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${
            live ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"
          }`}
        >
          <span
            className={`h-1.5 w-1.5 rounded-full ${
              live ? "animate-pulse bg-emerald-500" : "bg-slate-400"
            }`}
          />
          {live ? "Live" : "Offline"}
        </span>
      </div>

      {error && (
        <div className="rounded-lg bg-rose-50 px-4 py-3 text-sm text-rose-600">
          {error}
        </div>
      )}

      {bookings.length === 0 && !error ? (
        <div className="rounded-2xl border border-dashed border-slate-200 bg-white/50 p-10 text-center text-slate-400">
          No bookings yet. When a traveller books a flight it appears here
          instantly.
        </div>
      ) : (
        <div className="overflow-x-auto rounded-2xl border border-white/60 bg-white/85 shadow-sm backdrop-blur">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500">
              <tr>
                <th className="px-4 py-3">Reference</th>
                <th className="px-4 py-3">Booked by</th>
                <th className="px-4 py-3">Flight</th>
                <th className="px-4 py-3">Route</th>
                <th className="px-4 py-3">Departs</th>
                <th className="px-4 py-3">Passengers</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3 text-right">Total</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {bookings.map((b) => (
                <Fragment key={b.id}>
                  <tr
                    className={
                      flashId === b.id
                        ? "bg-emerald-50 transition-colors"
                        : "transition-colors"
                    }
                  >
                    <td className="px-4 py-3 font-mono font-semibold text-slate-700">
                      {b.reference}
                    </td>
                    <td className="px-4 py-3 text-slate-700">{b.bookedBy}</td>
                    <td className="px-4 py-3 text-slate-600">{b.flightNumber}</td>
                    <td className="px-4 py-3 text-slate-600">
                      {b.origin} → {b.destination}
                    </td>
                    <td className="px-4 py-3 text-slate-600">
                      {formatDateTime(b.departureTime)}
                    </td>
                    <td className="px-4 py-3 text-slate-600">
                      {b.passengers
                        .map((p) => `${p.firstName} ${p.lastName}`)
                        .join(", ")}
                    </td>
                    <td className="px-4 py-3">
                      <BookingStatusBadge status={b.status} />
                    </td>
                    <td className="px-4 py-3 text-right font-semibold text-slate-900">
                      {formatMoney(b.totalPrice, b.currency)}
                      {b.refundAmount > 0 && (
                        <div className="text-xs font-normal text-emerald-600">
                          refunded {formatMoney(b.refundAmount, b.currency)}
                        </div>
                      )}
                    </td>
                    <td className="px-4 py-3 text-right">
                      <button
                        onClick={() =>
                          setExpandedId(expandedId === b.id ? null : b.id)
                        }
                        className="text-xs font-medium text-indigo-600 hover:text-indigo-500"
                      >
                        {expandedId === b.id ? "Hide" : "Details"}
                      </button>
                    </td>
                  </tr>
                  {expandedId === b.id && (
                    <tr className="bg-slate-50/60">
                      <td colSpan={9} className="px-4 py-4">
                        <BookingDetails booking={b} />
                      </td>
                    </tr>
                  )}
                </Fragment>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}
